/* Check stack direction (0-down, 1-up) */
int f(int *a) {
  int b;
  if (&b > a) {
    printf("Stack grows upward\n");
    return 1;
  }
  printf("Stack grows downward\n");
  return 0;
}

/*
 Prevent compiler optimizations by calling function
